import React from 'react';

const QuanLyThongBao = () => {
    return (
        <div style={styles.chatGrid}>
            {/* Cột trái: Nhóm chung */}
            <div className="glass-card" style={styles.panel}>
                <div style={styles.header}>
                    <span style={styles.label}>Mọi người</span>
                </div>
                <div style={{...styles.body, backgroundImage: "url('../assets/nen_khung_chat.jpg')"}}>
                    {/* Tin nhắn ở đây */}
                </div>
            </div>

            {/* Cột phải: Gửi riêng */}
            <div className="glass-card" style={styles.panel}>
                <div style={{...styles.header, justifyContent: 'flex-end'}}>
                    <span style={{...styles.label, backgroundColor: '#a04e4e'}}>Gửi riêng</span>
                </div>
                <div style={styles.privateLayout}>
                    <div style={styles.roomList}>
                        {/* Các số phòng hình tròn */}
                        {['101', '102', '103'].map(id => <div key={id} className="room-circle">{id}</div>)}
                    </div>
                    <div style={styles.privateChat}></div>
                </div>
            </div>
        </div>
    );
};
// ... styles ...
export default QuanLyThongBao;
